"""Assemble only measured local experiments; missing evidence stays explicit."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'output';DEST=OUT/'comprehensive-review';DEST.mkdir(exist_ok=True)
def load(path):
 p=OUT/path;return json.loads(p.read_text()) if p.exists() else None
def esc(x):return html.escape(str(x))
labels=['original','floor-only','with-ceiling'];summary={'captures':{},'alignments':{},'visual':{},'depth_reference':{},'damage_filter':{},'benchmark_status':'not_evaluated_missing_independent_truth'};cards=[];ablations=[]
for label in labels:
 r=load(f'full-{label}/result.json');a=load(f'full-{label}-no-drift/result.json')
 if not r:continue
 summary['captures'][label]={'rooms':len(r['rooms']),'walls':len(r['structural_walls']),'openings':len(r['opening_candidates']),'candidate_area_m2':r['footprint_area']['value'],'local_heights_m':[x['ceiling_height']['value'] for x in r['rooms']],'seconds':r['timing_seconds'],'drift':r['diagnostics'][0]['drift']}
 rooms=''.join(f"<tr><td>{esc(room['name'])}</td><td>{room['floor_area']['value']:.2f}</td><td>{'unobserved' if room['ceiling_height']['value'] is None else format(room['ceiling_height']['value'],'.3f')}</td></tr>" for room in r['rooms'])
 cards.append(f"<article class='capture' id='{label}'><h2>{esc(label)}</h2><p>{len(r['rooms'])} region candidates · {len(r['structural_walls'])} wall planes · {len(r['opening_candidates'])} opening candidates</p><object type='image/svg+xml' data='../full-{label}/plan.svg'></object><div class='twocol'><table><tr><th>Region</th><th>Area m²</th><th>Height m</th></tr>{rooms}</table><div><p>Areas and heights are estimates with uncalibrated budgets. Region labels require review.</p><a href='../full-{label}/review.html'>Detailed capture review</a> · <a href='../full-{label}/result.json'>JSON</a> · <a href='../full-{label}/cloud.ply'>3D cloud</a></div></div></article>")
 if a:
  before=a['footprint_area']['value'];after=r['footprint_area']['value'];ablations.append(f"<tr><td>{label}</td><td>{len(a['rooms'])} → {len(r['rooms'])}</td><td>{before:.2f} → {after:.2f}</td><td>{after-before:+.2f}</td></tr>")
for pair in ['floor-ceiling','original-floor-only','original-with-ceiling']:
 r=load(f'alignment-{pair}/comparison.json')
 if r:summary['alignments'][pair]=r
align=''
for name,r in summary['alignments'].items():
 a=r['alignment'];pairs=r['comparison'];align+=f"<article><h3>{esc(name)}</h3><p>Median discrepancy {a['median_source_to_target_m']*100:.1f} cm · p90 {a['p90_source_to_target_m']*100:.1f} cm · overlap {a['source_overlap_within_10cm']:.0%}/{a['target_overlap_within_10cm']:.0%} · {len(pairs['rooms'])} region and {len(pairs['walls'])} wall matches</p><img src='../alignment-{name}/overlay.png' alt='Rigid alignment overlay'><a href='../alignment-{name}/comparison.json'>Full alignment diagnostics</a></article>"
visual=''
for label in labels+['property-photos']+[n+'-photos' for n in labels]:
 path=('metric-photos-'+label.removesuffix('-photos')) if label.endswith('-photos') and label!='property-photos' else (f'metric-video-{label}' if label!='property-photos' else 'metric-property-photos')
 nested=path+'/visual/0' if (OUT/path/'visual/0/sfm/reconstruction.json').exists() else path
 r=load(nested+'/thin-structure.json');sfm=load(nested+'/sfm/reconstruction.json')
 if sfm:
  item={'registered_images':sfm['registered_images'],'input_images':sfm['input_images'],'components':sfm['component_count'],'status':r['status'] if r else 'unresolved','rooms':len(r['rooms']) if r else 0,'metric_scale':r['diagnostics'].get('metric_scale') if r else None};summary['visual'][label]=item
  visual+=f"<tr><td>{label}</td><td>{item['registered_images']}/{item['input_images']}</td><td>{item['components']}</td><td>{item['status']}</td><td><a href='../{nested}/sfm/reconstruction.json'>Evidence</a></td></tr>"
reference=''
for label in labels:
 r=load(f'depth-reference-{label}/evaluation.json')
 if r:summary['depth_reference'][label]=r;reference+=f"<tr><td>{label}</td><td>{len(r['frames'])}</td><td>{r['median_frame_abs_relative_error']:.1%}</td></tr>"
damage=''
for label in labels:
 before=load(f'damage-{label}/damage.json');after=load(f'damage-filtered-{label}/damage.json')
 if before and after:
  summary['damage_filter'][label]={'before':len(before['candidates']),'after':len(after['candidates']),'frames':after['frames_assessed']}
  damage+=f"<tr><td>{label}</td><td>{len(before['candidates'])}</td><td>{len(after['candidates'])}</td></tr>"
(DEST/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
page="""<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>RoomScan · Complete data review</title><style>body{background:#edf1f6;color:#17243b;font:16px system-ui;margin:0}main{max-width:1150px;margin:auto;padding:36px}h1{font-size:38px;margin-bottom:8px}h2{font-size:26px}.intro{max-width:900px;line-height:1.7}.tag{display:inline-block;border-radius:20px;background:#fff0cf;color:#805719;padding:9px 14px}article,section{background:white;border-radius:16px;padding:25px;margin:24px 0;box-shadow:0 6px 22px #17243b08}object{width:100%;height:680px}img{max-width:100%;border-radius:8px}a{color:#2259ae}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:12px;text-align:left;border-bottom:1px solid #e2e8f0}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:25px}button{background:white;border:1px solid #9aaecb;border-radius:20px;padding:10px 18px;margin:6px;font:inherit;cursor:pointer}button.active{background:#17243b;color:white}.capture.hidden{display:none}li,p{line-height:1.65}@media(max-width:700px){main{padding:15px}.twocol{display:block}object{height:450px}}</style><main><span class='tag'>Prototype · physical gates unverified</span><h1>Complete data review</h1><p class='intro'>The three ZIPs are raw sensor captures. This review brings together structural LiDAR plans, drift ablations, cross-capture comparisons, image-only reconstruction and damage-proposal experiments. Candidate geometry and learned metric scale need verification against independent measurements.</p><div class='current'><strong>Latest geometry review · revision 2</strong><p>Wall-constrained free-space reconstruction, stronger wall/opening support, observed versus inferred coverage, and same-version drift comparison. Physical accuracy remains unverified.</p><a href='../improvement-review/index.html'>Open the current geometry comparison and implementation notes →</a></div><h2>Historical baseline results</h2><p>The scan plans and drift table below show the earlier geometry version. Use the current review above for revised candidates.</p><nav>"""+''.join(f"<button onclick=\"choose('{label}',this)\" class='{'active' if i==0 else ''}'>{label}</button>" for i,label in enumerate(labels))+"</nav>"+''.join(cards)+"""<section><h2>Drift correction on / off</h2><p>Bounded frame-to-model ICP changes both area and partitioning. Changed output does not establish improved physical accuracy. There is no global pose graph.</p><table><tr><th>Capture</th><th>Regions off → on</th><th>Area off → on, m²</th><th>Difference m²</th></tr>"""+''.join(ablations)+"</table></section><section><h2>All cross-capture comparisons</h2><p>Rigid registration preserves metric scale. These discrepancies measure geometric consistency; capture identity and physical accuracy remain unverified. Lower overlap in the original scan makes its correspondence less convincing.</p>"+align+"</section><section><h2>Image-only reconstruction</h2><p>Derived photo/video inputs are extracted from the supplied scans. The visual engine receives images alone. Fragmented components exclude other views and cannot certify a complete property. A model scale estimate does not pass the ±8% photo or ±3% video wall gates.</p><table><tr><th>Input</th><th>Registered / total</th><th>Components</th><th>Status</th><th>Details</th></tr>"+visual+"</table><h3>Learned depth against paired LiDAR</h3><p>Each frame uses upright RGB without sensor depth or poses as model input. The table shows the median of per-frame median absolute relative depth errors. LiDAR is a sensor reference, not independent ground truth. These are depth errors, not wall or area gate scores.</p><table><tr><th>Capture</th><th>Frames</th><th>Median relative depth error</th></tr>"+reference+"</table></section><section><h2>Damage proposals: before / after fixture filter</h2><p>The initial evidence includes fixtures and trim. Straight-edge rejection suppresses these confounders. The one remaining proposal also appears fixture-confounded in visual review. Surviving masks are unverified anomalies; no confirmed damage, concealed diagnosis or repair scope is established.</p><table><tr><th>Capture</th><th>Initial proposals</th><th>After filter</th></tr>"+damage+"</table><img src='../anomaly-contact-sheet.jpg' alt='Initial anomaly proposals include fixtures'><p>Initial evidence is preserved alongside masks, projected areas and surface IDs.</p></section><section><h2>What remains outside these data</h2><p>Independent tape/laser dimensions; repeat captures of verified rooms; staged and labelled damage; independent photos and video of the same property; competitor outputs; published Round 1 schema and gates. Calibration and benchmark pass claims remain unevaluated.</p><p><a href='../pdf/technical-report.pdf'>Technical report</a> · <a href='summary.json'>All comparison results</a> · <a href='../../docs/EXPANDED_ANALYSIS.md'>Implementation and limitations</a></p></section></main><script>function choose(id,button){document.querySelectorAll('.capture').forEach(c=>c.classList.toggle('hidden',c.id!==id));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b===button))}choose('original',document.querySelector('button'));</script></html>"
(DEST/'index.html').write_text(page);print(DEST/'index.html')
